<script setup lang="ts">
/**
 * Previous and next controls for a cursor-paged list (`design/components/cursor-pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/cursor-pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import { Icon, agentMember, devWarning, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/cursor-pagination.module.css'
import Button from '../controls/Button.vue'
import Inline from '../layout/Inline.vue'

export interface CursorPaginationMessages {
  previous: string
  next: string
  more?: string
  end?: string
}

export interface CursorPaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled
   * and none shows busy. Not `pending`, which says the pager's own request is in flight.
   */
  disabled?: boolean
  hasNext: boolean
  /**
   * Whether the list returned a cursor that way; controlled, as cursors belong to the list. The
   * append form does not read it: it has no previous direction.
   */
  hasPrevious: boolean
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CursorPaginationMessages
  /**
   * `replace` (the default) swaps the window for its neighbour, so the list stays bounded.
   * `append` is "Load more": one action that adds the next window below the ones on screen, for
   * a feed or a log read from the top.
   */
  mode?: 'replace' | 'append'
  /**
   * The next window's address, as `previousHref` is the previous one's: next, or in the append
   * form its action, is a link to it while it can be pressed, and a plain click calls `onNext`.
   */
  nextHref?: string
  /**
   * The requested window has not arrived: the pressed direction shows busy and the other is
   * disabled, so a slow fetch cannot be followed by a second request.
   */
  pending?: boolean
  /**
   * The current window in the app's words, such as "26–50" or "Newest first, page 2"; never a
   * total, because the list does not return one.
   */
  position?: string
  /**
   * The previous window's address, such as `?before=c25`. Given, previous is a link to it while
   * it can be pressed, so a crawler, a new tab and a reader whose script has not loaded can
   * follow it. A click the browser would follow in this tab calls `onPrevious` in place of the
   * navigation; a click with a modifier key opens the address. The append form does not read it:
   * it has no previous direction.
   */
  previousHref?: string
}

defineOptions({ name: 'CursorPagination', inheritAttrs: false })

const props = withDefaults(defineProps<CursorPaginationProps>(), {
  disabled: false,
  label: 'Pagination',
  messages: () => ({
    previous: 'Previous',
    next: 'Next',
    more: 'Load more',
    end: 'No more to load',
  }),
  mode: 'replace',
  pending: false,
})
const emit = defineEmits<{ next: []; previous: [] }>()
const listening = useListening()
const focused = ref(null as HTMLElement | null)
const focusedControl = ref(null as string | number | null)
const taken = ref(null as string | number | null)
const asked = ref(null as 'previous' | 'next' | null)
const paged = ref(false)
const root = useTemplateRef<HTMLElement>('root')
const more = computed(() => props.messages.more ?? 'Load more')
const end = computed(() => props.messages.end ?? 'No more to load')
const ended = computed(() => !props.hasNext && !props.pending)
const controls = computed(() =>
  props.mode === 'append' ? (props.hasNext || props.pending ? ['more'] : []) : ['previous', 'next'],
)
const focusIn = computed(() => (event: FocusEvent) => {
  const target = event.target as HTMLElement
  const pager = root.value as HTMLElement | null
  const names: readonly (string | number)[] = controls.value
  const at = pager === null ? -1 : [...pager.querySelectorAll('button, a[href]')].indexOf(target)
  focused.value = target
  focusedControl.value = at < 0 ? null : (names[at] ?? null)
})
const focusOut = computed(() => (event: FocusEvent) => {
  const target = event.target as HTMLElement
  if (target.matches(':disabled')) return
  queueMicrotask(() => {
    if (focused.value === target && target.isConnected) focused.value = null
  })
})
const keepPlace = computed(() => () => {
  const pager = root.value as HTMLElement | null
  if (pager === null) return
  const names: readonly (string | number)[] = controls.value
  const drawn = () => [...pager.querySelectorAll<HTMLElement>('button, a[href]')]
  const onPage = () => document.activeElement === null || document.activeElement === document.body
  const left = focused.value as HTMLElement | null
  if (left !== null && !left.isConnected) {
    focused.value = null
    const name = focusedControl.value
    const now = name === null ? undefined : drawn()[names.indexOf(name)]
    if (now !== undefined && onPage()) {
      if (now.matches(':disabled')) focused.value = now
      else now.focus()
    }
  }
  if (!props.disabled) {
    const control = taken.value
    taken.value = null
    if (control === null || document.activeElement !== pager) return
    const element = drawn()[names.indexOf(control)]
    if (element !== undefined && !element.matches(':disabled')) element.focus()
    return
  }
  const from = focused.value as HTMLElement | null
  if (from === null || !from.isConnected || !from.matches(':disabled')) return
  const active = document.activeElement
  if (active !== from && active !== null && active !== document.body) return
  taken.value = names[drawn().indexOf(from)] ?? null
  pager.focus()
})
const previousLink = computed(
  () => props.previousHref !== undefined && props.hasPrevious && !props.pending && !props.disabled,
)
const nextLink = computed(
  () => props.nextHref !== undefined && props.hasNext && !props.pending && !props.disabled,
)
const navigatesHere = computed(
  () =>
    (event: MouseEvent): boolean =>
      !event.defaultPrevented &&
      event.button === 0 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.shiftKey &&
      !event.altKey,
)
const followPrevious = computed(() => (event: MouseEvent): void => {
  if (!navigatesHere.value(event)) return
  event.preventDefault()
  asked.value = 'previous'
  emit('previous')
})
const followNext = computed(() => (event: MouseEvent): void => {
  if (!navigatesHere.value(event)) return
  event.preventDefault()
  asked.value = 'next'
  if (props.mode === 'append') paged.value = true
  emit('next')
})
const effect1 = () => {
  props.pending || (asked.value = null)
}
watch(() => props.pending, effect1, { flush: 'post' })
const effect2 = () => {
  devWarning(
    props.mode !== 'append' && props.hasPrevious && !listening.previous,
    'CursorPagination: `hasPrevious` with no `onPrevious` draws a previous button that does nothing.',
  )
}
onMounted(effect2)
watch(() => props.mode !== 'append' && props.hasPrevious && !listening.previous, effect2, {
  flush: 'post',
})
const effect3 = () => {
  devWarning(
    props.mode === 'append' &&
      (props.messages.more === undefined || props.messages.end === undefined),
    'CursorPagination: the append form shows `messages.more` and `messages.end`; pass them with the others, so one control never mixes two languages.',
  )
}
onMounted(effect3)
watch(
  () =>
    props.mode === 'append' &&
    (props.messages.more === undefined || props.messages.end === undefined),
  effect3,
  { flush: 'post' },
)
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const run = () => {
    keepPlace.value()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [root.value])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled'],
      })
  release4 = () => {
    mutation?.disconnect()
  }
  run()
}
onMounted(effect4)
watch(
  () =>
    props.mode === 'append'
      ? props.hasNext || props.pending || paged.value
      : props.hasPrevious || props.hasNext || props.pending,
  effect4,
  { flush: 'post' },
)
onBeforeUnmount(() => release4?.())
const effect5 = () => {
  keepPlace.value()
}
watch(() => props.disabled, effect5, { flush: 'post' })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'CursorPagination',
    element: () => root.value,
    state: () => ({
      'has-previous': props.mode !== 'append' && props.hasPrevious,
      'has-next': props.hasNext,
      position: props.position ?? '',
      pending: props.pending,
      disabled: props.disabled,
    }),
    actions: {
      previous: () =>
        (() => {
          if (props.mode === 'append') throw new Error('The append form has no previous window.')
          if (!props.hasPrevious) throw new Error('There is no previous window.')
          if (props.pending) throw new Error('A window is in flight; wait for it to arrive.')
          asked.value = 'previous'
          emit('previous')
        })(),
      next: () =>
        (() => {
          if (!props.hasNext) throw new Error('There is no next window.')
          if (props.pending) throw new Error('A window is in flight; wait for it to arrive.')
          asked.value = 'next'
          if (props.mode === 'append') paged.value = true
          emit('next')
        })(),
    },
    withholds: () => root.value,
  })
  release6 = () => {
    ran()
  }
}
onMounted(effect6)
onBeforeUnmount(() => release6?.())
</script>

<template>
  <nav
    v-if="mode === 'append' ? hasNext || pending || paged : hasPrevious || hasNext || pending"
    ref="root"
    :class="styles.pagination"
    :aria-label="label"
    :aria-busy="pending ? true : undefined"
    :data-pending="pending ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    tabindex="-1"
    data-member="cursor-pagination"
    @focusin="focusIn($event)"
    @focusout="focusOut($event)"
  >
    <Inline :gap="2" align="center" :wrap="true">
      <template v-if="mode === 'append'">
        <!-- position -->
        <span v-if="position !== undefined" :class="styles.position" aria-live="polite">
          {{ position }}
        </span>
        <!-- link -->
        <a
          v-if="!ended && nextLink"
          :class="styles.link"
          :href="nextHref"
          data-variant="outline"
          data-size="sm"
          data-tone="neutral"
          @click="followNext($event)"
        >
          <!-- label -->
          <span :class="styles.linkLabel">
            {{ more }}
          </span>
        </a>
        <Button
          v-else-if="!ended"
          variant="outline"
          tone="neutral"
          size="sm"
          :label="more"
          :loading="pending"
          :disabled="disabled && !pending"
          @click="((asked = 'next'), (paged = true), emit('next'))"
        />
      </template>
      <template v-else>
        <!-- link -->
        <a
          v-if="previousLink"
          :class="styles.link"
          :href="previousHref"
          data-variant="ghost"
          data-size="sm"
          data-tone="neutral"
          @click="followPrevious($event)"
        >
          <!-- glyph -->
          <span :class="styles.linkGlyph">
            <Icon name="previous" size="sm" />
          </span>
          <!-- label -->
          <span :class="styles.linkLabel">
            {{ messages.previous }}
          </span>
        </a>
        <Button
          v-else
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="previous"
          :label="messages.previous"
          :loading="pending && asked === 'previous'"
          :disabled="!hasPrevious || (pending ? asked !== 'previous' : disabled)"
          @click="((asked = 'previous'), emit('previous'))"
        />
        <!-- position -->
        <span v-if="position !== undefined" :class="styles.position" aria-live="polite">
          {{ position }}
        </span>
        <!-- link -->
        <a
          v-if="nextLink"
          :class="styles.link"
          :href="nextHref"
          data-variant="ghost"
          data-size="sm"
          data-tone="neutral"
          @click="followNext($event)"
        >
          <!-- label -->
          <span :class="styles.linkLabel">
            {{ messages.next }}
          </span>
          <!-- glyph -->
          <span :class="styles.linkGlyph">
            <Icon name="next" size="sm" />
          </span>
        </a>
        <Button
          v-else
          variant="ghost"
          tone="neutral"
          size="sm"
          trailingIcon="next"
          :label="messages.next"
          :loading="pending && asked === 'next'"
          :disabled="!hasNext || (pending ? asked !== 'next' : disabled)"
          @click="((asked = 'next'), emit('next'))"
        />
      </template>
    </Inline>
    <!-- end -->
    <span v-if="mode === 'append'" :class="styles.end" role="status">
      <template v-if="ended">{{ end }}</template>
    </span>
  </nav>
</template>
